<?php
/**
 * The Template for displaying all single products (Trendino Custom PDP)
 *
 * @package Trendino
 */

if ( ! defined( 'ABSPATH' ) ) {
    exit;
}

get_header();

while ( have_posts() ) :
    the_post();
    global $product;

    if ( ! is_a( $product, 'WC_Product' ) ) {
        $product = wc_get_product( get_the_ID() );
    }

    $product_id        = $product->get_id();
    $main_image_id     = $product->get_image_id();
    $gallery_image_ids = $product->get_gallery_image_ids();
    $all_images        = array_unique( array_filter( array_merge( array( $main_image_id ), $gallery_image_ids ) ) );

    // Custom Meta Data
    $en_title          = get_post_meta( $product_id, '_tno_en_title', true );
    $badge_text        = get_post_meta( $product_id, '_tno_badge_text', true ) ?: 'تضمین اصالت و سلامت فیزیکی کالا';
    $seller_name       = get_post_meta( $product_id, '_tno_seller_name', true ) ?: get_bloginfo( 'name' );
    $seller_perf       = get_post_meta( $product_id, '_tno_seller_perf', true ) ?: 'عملکرد عالی';
    $warranty_text     = get_post_meta( $product_id, '_tno_warranty_text', true ) ?: 'گارانتی ۱۸ ماهه شرکتی معتبر';
    $shipping_text     = get_post_meta( $product_id, '_tno_shipping_text', true ) ?: 'موجود در انبار فروشنده (ارسال فوری)';
    $club_points       = get_post_meta( $product_id, '_tno_club_points', true ) ?: '۱۵۰';
    $return_alert      = get_post_meta( $product_id, '_tno_return_alert', true ) ?: 'درخواست مرجوع کردن کالا در گروه موبایل و کالای دیجیتال تنها با دلیل «انصراف از خرید» و در صورت باز نشدن پلمپ کالا امکان‌پذیر است.';
    $installment_title = get_post_meta( $product_id, '_tno_installment_title', true ) ?: 'خرید اقساطی آسان و بدون ضامن';
    $installment_sub   = get_post_meta( $product_id, '_tno_installment_sub', true ) ?: 'با اعتبار اسنپ‌پی یا ازکی‌وام در ۴ قسط بدون سود خرید کنید';
    $installment_link  = get_post_meta( $product_id, '_tno_installment_link', true ) ?: '#';
    $free_ship_title   = get_post_meta( $product_id, '_tno_free_ship_title', true ) ?: 'ارسال رایگان برای این محصول';

    $key_features      = TNO_PDP_Manager::get_product_key_features( $product );
    $spec_groups       = TNO_PDP_Manager::get_product_spec_groups( $product );
    $criteria_averages = TNO_PDP_Manager::get_product_criteria_averages( $product_id );

    // Ratings & Counts
    $avg_rating   = (float) $product->get_average_rating() ?: 4.5;
    $review_count = (int) $product->get_review_count();

    $reviews = get_comments( array(
        'post_id' => $product_id,
        'status'  => 'approve',
        'type'    => 'review',
        'orderby' => 'comment_date_gmt',
        'order'   => 'DESC',
    ) );

    $questions = get_comments( array(
        'post_id' => $product_id,
        'status'  => 'approve',
        'type__in' => array( 'tno_question', 'tno_qa' ),
        'parent'  => 0,
        'orderby' => 'comment_date_gmt',
        'order'   => 'DESC',
    ) );
    $qa_count = count( $questions );

    // Price & Discount Calculation
    $regular_price = (float) $product->get_regular_price();
    $sale_price    = (float) $product->get_sale_price();
    $active_price  = (float) $product->get_price();
    if ( $product->is_type( 'variable' ) ) {
        $regular_price = (float) $product->get_variation_regular_price( 'min' );
        $sale_price    = (float) $product->get_variation_sale_price( 'min' );
        $active_price  = (float) $product->get_variation_price( 'min' );
    }
    $discount_pct = ( $regular_price > 0 && $sale_price > 0 && $regular_price > $sale_price )
        ? round( ( ( $regular_price - $sale_price ) / $regular_price ) * 100 )
        : 0;

    // AI Summary
    $ai_summary = get_post_meta( $product_id, '_tno_ai_summary', true );
    if ( empty( $ai_summary ) ) {
        $ai_summary = 'بر اساس تحلیل دیدگاه‌های ثبت‌شده توسط خریداران، این محصول از نظر کیفیت ساخت، طراحی ظاهری و ارزش خرید نسبت به قیمت، رضایت بالایی را کسب کرده است و برای استفاده روزمره و حرفه‌ای گزینه‌ای مطمئن محسوب می‌شود.';
    }
    $ai_pros = array_filter( array_map( 'trim', explode( ',', get_post_meta( $product_id, '_tno_ai_pros', true ) ?: 'کیفیت ساخت بالا,ارزش خرید مناسب,عملکرد روان و سریع' ) ) );
    $ai_cons = array_filter( array_map( 'trim', explode( ',', get_post_meta( $product_id, '_tno_ai_cons', true ) ?: 'لوازم جانبی محدود در جعبه' ) ) );
    ?>

    <!-- Breadcrumb Bar -->
    <?php TNO_PDP_Manager::render_breadcrumb( $product ); ?>

